#define MSC_TRIGGER_KEY SG_KEY_OPT


void boot_screen() {
    M5.Display.fillScreen(BLACK);
    M5.Display.drawBitmap(0, 0, epd_bitmap_bootlogo, 240, 135, (uint16_t)THEME_COLOR, (uint16_t)BLACK);

    M5.Display.setTextDatum(BC_DATUM);
    M5.Display.setTextColor(THEME_COLOR, BLACK);
    M5.Display.setTextSize(2);
    M5.Display.setFont(&fonts::DejaVu9); 
    M5.Display.drawString("Singularity", 120, 120);

    unsigned long start = millis();
    bool opt_was_pressed = false;
    unsigned long last_trigger = 0;
    const unsigned long TRIGGER_COOLDOWN_MS = 1000;

    while (millis() - start < BOOT_DELAY_MS) {
        M5Cardputer.update();


        bool opt_is_pressed = false;
        if (M5Cardputer.Keyboard.isPressed()) {
            auto status = M5Cardputer.Keyboard.keysState();
            opt_is_pressed = status.opt;
        }

        unsigned long now = millis();

        if (opt_is_pressed && !opt_was_pressed && (now - last_trigger > TRIGGER_COOLDOWN_MS)) {
            last_trigger = now;
            enter_msc_mode();
        }

        opt_was_pressed = opt_is_pressed;

        delay(10);
    }
        
    M5.Display.setFont(&fonts::Font0);
    M5.Display.setTextDatum(TL_DATUM);
}